solution.solution.cpp:
#include <array>
#include <memory>
#include <string>
#include <vector>

class Trie
{
public:
    bool insert(const std::string& word)
    {
        if (contains(word)) return false;
        Node* n = &root_;
        ++n->passing;
        for (char ch : word)
        {
            auto& child = n->next[ch - 'a'];
            if (!child) child = std::make_unique<Node>();
            n = child.get();
            ++n->passing;
        }
        n->word = true;
        return true;
    }

    bool erase(const std::string& word)
    {
        if (!contains(word)) return false;
        Node* n = &root_;
        --n->passing;
        for (char ch : word)
        {
            auto& child = n->next[ch - 'a'];
            if (--child->passing == 0)
            {
                child.reset();                     // nothing else passes through: drop the whole branch
                return true;
            }
            n = child.get();
        }
        n->word = false;
        return true;
    }

    bool contains(const std::string& word) const
    {
        const Node* n = walk(word);
        return n && n->word;
    }

    int countPrefix(const std::string& prefix) const
    {
        const Node* n = walk(prefix);
        return n ? n->passing : 0;
    }

    std::vector<std::string> complete(const std::string& prefix, std::size_t limit) const
    {
        std::vector<std::string> out;
        std::string current = prefix;
        if (const Node* n = walk(prefix)) collect(n, current, limit, out);
        return out;
    }

    std::string longestCommonPrefix() const
    {
        std::string out;
        const Node* n = &root_;
        if (n->passing == 0) return out;
        while (!n->word)
        {
            const Node* only = nullptr;
            int children = 0;
            char letter = 0;
            for (int c = 0; c < 26; ++c)
                if (n->next[c]) { ++children; only = n->next[c].get(); letter = static_cast<char>('a' + c); }
            if (children != 1) break;
            out += letter;
            n = only;
        }
        return out;
    }

    std::size_t size() const { return static_cast<std::size_t>(root_.passing); }

private:
    struct Node
    {
        std::array<std::unique_ptr<Node>, 26> next{};
        bool word = false;
        int passing = 0;
    };

    const Node* walk(const std::string& s) const
    {
        const Node* n = &root_;
        for (char ch : s)
        {
            n = n->next[ch - 'a'].get();
            if (!n) return nullptr;
        }
        return n;
    }

    static void collect(const Node* n, std::string& current, std::size_t limit, std::vector<std::string>& out)
    {
        if (out.size() >= limit) return;
        if (n->word) out.push_back(current);
        for (int c = 0; c < 26 && out.size() < limit; ++c)
            if (n->next[c])
            {
                current.push_back(static_cast<char>('a' + c));
                collect(n->next[c].get(), current, limit, out);
                current.pop_back();
            }
    }

    Node root_;
};

std::vector<int> prefixFunction(const std::string& p)
{
    std::vector<int> pi(p.size(), 0);
    for (std::size_t i = 1, k = 0; i < p.size(); ++i)
    {
        while (k > 0 && p[i] != p[k]) k = static_cast<std::size_t>(pi[k - 1]);
        if (p[i] == p[k]) ++k;
        pi[i] = static_cast<int>(k);
    }
    return pi;
}

std::vector<std::size_t> findAll(const std::string& text, const std::string& pattern)
{
    std::vector<std::size_t> found;
    if (pattern.empty()) return found;
    std::vector<int> pi = prefixFunction(pattern);
    for (std::size_t i = 0, k = 0; i < text.size(); ++i)
    {
        while (k > 0 && text[i] != pattern[k]) k = static_cast<std::size_t>(pi[k - 1]);
        if (text[i] == pattern[k]) ++k;
        if (k == pattern.size())
        {
            found.push_back(i + 1 - pattern.size());
            k = static_cast<std::size_t>(pi[k - 1]);
        }
    }
    return found;
}

unitTests:
TEST("insert and look up") {
    Trie t;
    for (std::string w : { "tea", "ten", "to", "inn", "in", "i", "team", "tease", "tent" }) CHECK(t.insert(w));
    CHECK(!t.insert("tea"));
    CHECK_EQ(t.size(), std::size_t{ 9 });
    CHECK(t.contains("in"));
    CHECK(!t.contains("te"));
    CHECK(!t.contains("teams"));
    CHECK_EQ(t.countPrefix("te"), 5);
    CHECK_EQ(t.countPrefix("i"), 3);
    CHECK_EQ(t.countPrefix(""), 9);
    CHECK_EQ(t.countPrefix("x"), 0);
}
TEST("completion") {
    Trie t;
    for (std::string w : { "tea", "ten", "to", "inn", "in", "team", "tease", "tent" }) t.insert(w);
    CHECK_EQ(t.complete("te", 3), (std::vector<std::string>{ "tea", "team", "tease" }));
    CHECK_EQ(t.complete("te", 10), (std::vector<std::string>{ "tea", "team", "tease", "ten", "tent" }));
    CHECK_EQ(t.complete("in", 10), (std::vector<std::string>{ "in", "inn" }));
    CHECK(t.complete("q", 5).empty());
    CHECK(t.complete("te", 0).empty());
}
TEST("erasing") {
    Trie t;
    for (std::string w : { "car", "card", "care", "cart" }) t.insert(w);
    CHECK(t.erase("car"));
    CHECK(!t.erase("car"));
    CHECK(!t.contains("car"));
    CHECK(t.contains("card"));
    CHECK_EQ(t.countPrefix("car"), 3);
    CHECK(t.erase("card"));
    CHECK(t.erase("care"));
    CHECK(t.erase("cart"));
    CHECK_EQ(t.size(), std::size_t{ 0 });
    CHECK_EQ(t.countPrefix("c"), 0);
    CHECK(t.complete("", 5).empty());
    CHECK(t.insert("cab"));
    CHECK_EQ(t.complete("c", 5), (std::vector<std::string>{ "cab" }));
    CHECK(t.insert(""));
    CHECK(t.contains(""));
}
TEST("longest common prefix") {
    Trie t;
    CHECK_EQ(t.longestCommonPrefix(), std::string(""));
    for (std::string w : { "interview", "internet", "interval", "internal" }) t.insert(w);
    CHECK_EQ(t.longestCommonPrefix(), std::string("inter"));
    t.insert("in");
    CHECK_EQ(t.longestCommonPrefix(), std::string("in"));
    Trie one;
    one.insert("solo");
    CHECK_EQ(one.longestCommonPrefix(), std::string("solo"));
}
TEST("prefix function and search") {
    CHECK_EQ(prefixFunction("ababaca"), (std::vector<int>{ 0, 0, 1, 2, 3, 0, 1 }));
    CHECK_EQ(prefixFunction("aabaa"), (std::vector<int>{ 0, 1, 0, 1, 2 }));
    CHECK_EQ(findAll("abababcabababcab", "ababc"), (std::vector<std::size_t>{ 2, 9 }));
    CHECK_EQ(findAll("aaaa", "aa"), (std::vector<std::size_t>{ 0, 1, 2 }));
    CHECK(findAll("abc", "").empty());
    CHECK(findAll("ab", "abc").empty());
    std::string big(1000000, 'a');
    big[999999] = 'b';
    std::string pattern(5000, 'a');
    pattern.back() = 'b';
    CHECK_EQ(findAll(big, pattern), (std::vector<std::size_t>{ 995000 }));
    std::string text(1000000, 'a');
    CHECK_EQ(findAll(text, "aaa").size(), std::size_t{ 999998 });
}

